\draw[red!75!black, thin] let \p1 = ($(E)-(F)$), \p2 = ($(A)-(F)$) in ($(F) + ({atan2(\y1,\x1)}:0.65)$) arc ({atan2(\y1,\x1)}:{atan2(\y2,\x2)}:0.65);
